css:
.nkt-dot { font-family: "Courier New", Courier, monospace; font-size: 11px; color:#111; }
.nkt-dot .top { display:flex; justify-content:space-between; align-items:flex-start; }
.nkt-dot .title { text-align:center; font-size:15px; font-weight:700; letter-spacing:.2px; }
.nkt-dot table { width:100%; border-collapse:collapse; }
.nkt-dot th, .nkt-dot td { padding:3px 4px; vertical-align:top; }
.nkt-dot .items { margin-top:8px; border-top:1px solid #111; border-bottom:1px solid #111; }
.nkt-dot .items th { border-bottom:1px solid #111; text-align:left; }
.nkt-dot .num { text-align:right; white-space:nowrap; }
.nkt-dot .center { text-align:center; }
.nkt-dot .balances { width:48%; margin-left:auto; margin-top:8px; }
.nkt-dot .balances td { padding:2px 3px; }
.nkt-dot .signature { width:38%; margin-left:auto; margin-top:34px; border-top:1px solid #111; text-align:center; padding-top:3px; font-weight:700; }
.nkt-dot .small { font-size:9px; }
@media print { .nkt-dot tr { page-break-inside:avoid; } }
